[
  {
    "name": "华锐金融大厦·外景",
    "description": "深夜的摩天大楼，几扇孤独的灯，玻璃幕墙反射城市冷光，公司秘密的物理象征",
    "visualStyle": "16:9宽幅构图，垂直玻璃幕墙与冷蓝天空形成压迫感，城市霓虹在玻璃上的反射作为色彩来源，整体高对比冷蓝调"
  },
  {
    "name": "32楼开放办公区",
    "description": "林夏深夜加班的主要空间，无边无际的工位、荧光灯频闪、打印机指示灯冷光",
    "visualStyle": "冷白荧光灯与漆黑窗外形成强烈反差，玻璃隔断制造视觉纵深，背景无数关闭的电脑屏幕形成阵列感压迫，色调冷蓝灰"
  },
  {
    "name": "32楼茶水间",
    "description": "深夜唯一有暖光的角落，自动咖啡机、台灯、贴满便利贴的冰箱",
    "visualStyle": "唯一暖黄光源点，与外部冷蓝办公区形成强烈对比，象征林夏此刻内心的最后一丝温暖"
  },
  {
    "name": "38楼财务总监办公室",
    "description": "周建国的私人领地，深色木质家具、皮质沙发、巨大落地窗俯瞰城市",
    "visualStyle": "深色调，胡桃木与皮革质感，单一金色台灯打出的硬光在脸上形成戏剧性阴影，窗外城市灯火如棋盘"
  },
  {
    "name": "一楼大堂",
    "description": "深夜空旷的旋转门与保安台，老王的位置",
    "visualStyle": "大理石冷白反光，单点顶灯形成孤岛光，老王位于光下，背后是巨大的黑暗门厅"
  },
  {
    "name": "天台",
    "description": "第一集高潮，林夏与苏晴对峙真相的风暴中心，俯瞰整个城市灯火",
    "visualStyle": "风大、雾气、城市灯火如星海，头顶探照灯形成间歇性扫光，营造舞台剧般的仪式感"
  }
]

{
  "scenes": [
    {
      "location": "华锐金融大厦·外景",
      "time": "深夜 23:47",
      "characters": [
        "林夏"
      ],
      "action": "空旷的城市街道，林夏背着电脑包独自走向华锐大厦，大堂只剩老王一人在值班",
      "dialogue": "（无对白，只听见高跟鞋踩在石板路上的清脆回响）",
      "mood": "孤绝、压抑、城市巨大而个人渺小"
    },
    {
      "location": "32楼开放办公区",
      "time": "凌晨 00:15",
      "characters": [
        "林夏"
      ],
      "action": "林夏独自坐在工位上处理报表，电脑屏幕荧光映在脸上，咖啡已经凉透。她揉了揉太阳穴，站起来走向茶水间",
      "dialogue": "（屏幕弹出无数报错提醒，林夏小声叹气）",
      "mood": "疲惫、机械、被工作吞噬的麻木"
    },
    {
      "location": "32楼茶水间",
      "time": "凌晨 00:32",
      "characters": [
        "林夏",
        "苏晴"
      ],
      "action": "林夏在茶水间倒咖啡时偶遇同样深夜未眠的苏晴，两人闲聊中苏晴无意提及一笔与周建国有关的奇怪海外转账",
      "dialogue": "苏晴：'诶，你听说没？周总最近让财务部加急处理一笔离岸转账，走的是三家没听过的小公司。'\n林夏：'离岸？这金额多少？'\n苏晴：'小两亿吧，但奇怪的是没人知道收款方是谁。'",
      "mood": "短暂的温暖与好奇，苏晴的出现带来一丝人性温度，也投下第一颗怀疑的种子"
    },
    {
      "location": "32楼开放办公区",
      "time": "凌晨 01:08",
      "characters": [
        "林夏"
      ],
      "action": "林夏回到工位，表面上继续做表，实际上偷偷在另一个窗口查询周建国的公开信息，越查越心悸",
      "dialogue": "（无对白，林夏呼吸逐渐加重）",
      "mood": "好奇转向恐惧，冷静的键盘敲击声逐渐被心跳声盖过"
    },
    {
      "location": "32楼走廊",
      "time": "凌晨 01:34",
      "characters": [
        "林夏"
      ],
      "action": "林夏借口去卫生间，悄悄绕到38楼财务部所在的走廊尽头，她听见里面有动静，趴在玻璃门上向里窥视",
      "dialogue": "（无对白，只有自己急促的呼吸）",
      "mood": "高度紧张，第一次跨入不该进入的空间，窥视欲与恐惧交织"
    },
    {
      "location": "38楼财务总监办公室门外",
      "time": "凌晨 01:36",
      "characters": [
        "林夏",
        "周建国"
      ],
      "action": "透过磨砂玻璃的缝隙，林夏看见周建国背对门口，正将一叠文件塞进碎纸机，并反复格式化一台独立电脑",
      "dialogue": "（无对白，只有碎纸机的嗡鸣与格式化进度条的声音）",
      "mood": "窥见罪恶的惊悚，碎纸机的白噪音形成心理压迫"
    },
    {
      "location": "32楼走廊",
      "time": "凌晨 01:42",
      "characters": [
        "林夏"
      ],
      "action": "林夏被一只突然伸出的手按住肩膀——是周建国。他温和地笑着说'这么晚还在加班？'，眼神却冷得像刀",
      "dialogue": "周建国：'小林啊，这么晚还在？身体要紧。'\n林夏：'周……周总好。'\n周建国：'38楼可不能乱走，明天还有会，早点回去。'",
      "mood": "被猎人注视的窒息感，温和语气的背后是赤裸裸的威胁"
    },
    {
      "location": "一楼大堂",
      "time": "凌晨 02:10",
      "characters": [
        "林夏",
        "老王"
      ],
      "action": "林夏仓皇下到大堂，老王正在擦桌子，看见她神色不对，默默递上一杯热水",
      "dialogue": "老王：'姑娘，电梯里有监控，你小心点。'\n林夏：'……谢谢您。'\n老王：'这楼里待久了，谁没点秘密呢。'",
      "mood": "底层人的善良与胆怯交织，老王的一句话是善意的提醒也是无奈的共谋"
    },
    {
      "location": "天台",
      "time": "凌晨 02:36",
      "characters": [
        "林夏"
      ],
      "action": "林夏没有回家，独自爬上大厦天台，俯瞰整个城市灯火，风吹乱她的头发，她握着手机，眼神从恐惧慢慢转为坚定",
      "dialogue": "（内心独白）林夏：'他们以为我只是一个没人会注意的实习生……'\n（镜头慢慢推向她的眼睛）林夏：'但他们错了。'",
      "mood": "从孤独绝望到觉醒决意的情绪顶点，冰冷的风与燃烧的内心形成强烈反差"
    }
  ]
}
